// Norwegian brand copy. This file mirrors `content.mjs` key for key: the pages, the
// Evensen story, the materials guide and the journal are written for a Norwegian reader
// rather than translated sentence by sentence. `content.test.mjs` fails when a key is
// missing on either side.

export const CONTENT_PAGES = {
  "/pages/our-philosophy": { title: "Sirkulære sko og vår filosofi", eyebrow: "Vår filosofi", heading: "Derfor finnes vi", copy: `<p>New Movements ble grunnlagt i Oslo i 2017 av Martin Evensen, skomaker i fjerde generasjon, og har vokst til å bli en ledende aktør innen sirkulære sko i premiumsegmentet. Med dyp respekt for naturen, europeisk håndverk og familiearven forener vi nytenkning og tradisjon i forfinede sko av uvanlig god kvalitet.</p><p>Sirkularitet har alltid ligget i ryggmargen til New Movements – fra den første skoen til verdens første resirkuleringsprogram for sko. Vi fortsetter reisen mot en ny standard for ansvarlig premiumhåndverk, og former den moderne garderoben med hensikt, presisjon og rolig selvtillit.</p><h2>Problemet</h2><p>Hvert år produseres det rundt 25 milliarder par sko i verden, og hele 95 prosent av dem ender på fyllplassen. Det sløser bort verdifulle materialer, og det bidrar kraftig til forurensning og tap av ressurser.</p><h2>Oppdraget vårt</h2><p>Martin Evensen grunnla New Movements med et tydelig mål: å endre skobransjen ved å lage den perfekte sirkulære skoen. Vi vil bryte avfallets kretsløp ved å sørge for at hvert par vi lager kan resirkuleres i sin helhet. Da blir belastningen på miljøet mindre, og veien videre mer bærekraftig.</p><h2>La oss bevege oss</h2><p>Å ta på seg skoene våre er å kjenne på hva det vil si å kjøpe seg inn i sirkulærøkonomien. For det skjer noe når vi tar inn over oss de nye bevegelsene vi selv setter i gang, hvor små de enn er. Små dråper lager ringer i vannet, og ringene blir bølger. New Movements sender folk ut på sin egen vei mot å ta vare på og hele planeten, og inspirerer dem til å starte nye bevegelser selv.</p><h2>Det vi gjør</h2><h3>Vi beveger mennesker</h3><p>New Movements er ikke bare et selskap som lager sko. Vi er en gjeng mennesker med et kall om å drive en virksomhet som lever i harmoni med planeten – og vi tror på å utfordre andre til å gjøre det samme. Det gjør vi gjennom skoene vi lager. Dette er vår bevegelse for å gjøre verden litt bedre.</p><h3>Designfilosofi</h3><p>Tilnærmingen vår handler om mer enn estetikk. Vi tror på å forene nytenkning og hensikt, og lage sko som ikke bare er pene og komfortable, men også laget for å vare – og til slutt for å resirkuleres. Denne filosofien styrer hver beslutning vi tar, fra valg av materialer til utformingen av leverandørkjeden.</p><h3>Etisk produksjon</h3><p>Vi er forpliktet til etisk produksjon. Det betyr at vi velger produsenter som gir rettferdig lønn, trygge arbeidsforhold og respekt for dem som jobber der. Fabrikkene våre i Portugal og Spania viser at ansvarlig produksjon er mulig i motebransjen.</p><h3>Sirkulære materialer</h3><p>Hver enkelt del av skoene våre er valgt med miljøet i tankene. Vi prioriterer økologiske, resirkulerte og resirkulerbare materialer, og flytter stadig grensen for hva som er mulig.</p><h2>Slik gjør vi det</h2><h3>Innovasjon og utvikling</h3><p>Vi arbeider helt i front av materialteknologi og sirkulært design. Sammen med ledende forskningsmiljøer som SINTEF utvikler vi nye materialer og produksjonsmetoder som kan flytte bærekraften i skobransjen. Målet er sko som kan gå fra sko til sko til sko i et lukket kretsløp.</p><h3>Resirkuleringsprogram</h3><p>Resirkuleringsprogrammet vårt er sirkularitet i praksis. Du kan levere inn utslitte New Movements-sko til resirkulering og få 20 prosent rabatt på neste kjøp. Materialene får nytt liv, og du blir selv en del av sirkulærøkonomien.</p><h3>Fellesskap og kunnskap</h3><p>Vi tror på fellesskap og kunnskap. Gjennom nettsiden, sosiale medier og arrangementer i NM-butikken deler vi hvorfor sirkulært design, bevisste valg og konsekvensene av dem betyr noe. Bli med oss – ett par sko av gangen.</p>` },
  "/pages/recycle": { title: "Resirkulering av sko", eyebrow: "20 % resirkulering", heading: "Derfor resirkulerer vi", copy: `<p>Mote- og skobransjen står for en stor del av avfallet i verden. Over 22 milliarder par sko kastes hvert år, og 90 prosent av dem ender på fyllplassen. De aller fleste kan ikke resirkuleres, og det gir store klimagassutslipp og tap av natur. I New Movements utfordrer vi dette ved å gjøre sirkularitet til grunnsteinen i en bærekraftig fremtid for mote.</p><h2>Hva skjer med skoene du leverer inn</h2><p>Gjennom NM-resirkuleringsprogrammet, som vi startet i 2020, har vi gjort det enkelt å sende inn utslitte sko. Hvert par går tilbake til produsentene våre, der viktige materialer skilles ut, bearbeides og brukes på nytt. Hvor mye som kan resirkuleres varierer fra modell til modell, og vi jobber hele tiden med å hente ut mer av materialene og kaste mindre.</p><h2>Slik leverer du inn skoene</h2><p>Å være med er enkelt: følg instruksjonene i denne delen for å sende skoene tilbake til oss. Som takk for bidraget får du 20 prosent rabatt på neste kjøp. Skoene dine får nytt liv, og sammen reduserer vi fotavtrykket et skritt nærmere målet om en helt sirkulær verdikjede.</p><p>Når du leverer inn et utslitt par, blir hele livsløpet til skoene synlig. Les mer om hvilken forskjell valget ditt gjør, og se hvordan hver sko blir en ny begynnelse. Bli med på resirkuleringen, og se hva vi får til sammen. Sammen kan vi tegne skobransjens fremtid på nytt.</p><p>Vil du resirkulere utslitte New Movements-sko – og det håper vi at du vil – kan du stikke innom <a href="https://maps.app.goo.gl/TheZsfUEc8qxNy2j8" rel="external">NM Community Center</a> på Steen &amp; Strøm i Oslo, gå til en av forhandlerne våre (helst der du kjøpte dem), eller sende oss en e-post på <a href="mailto:store@newmovements.com">store@newmovements.com</a>.</p>` },
  "/pages/shoe-care": { title: "Skopleieguide", eyebrow: "Pleieguide", heading: "Hold paret i bevegelse", copy: `<p>God pleie holder materialene myke, bevarer overflaten og gjør at skoene fungerer lenger. Fjern alltid løst smuss først, test produkter på et skjult område, og la skoene tørke naturlig.</p><h2>Skinn</h2><p>Børst bort støv med en myk børste, og legg på litt nøytral lærkrem eller lærvoks med en ren klut. La det trekke inn før du polerer. Ikke bløtlegg skinnet, og tørk det aldri rett på en radiator eller ved en varmekilde.</p><h2>Semsket skinn og nubuck</h2><p>Bruk en semsket børste for å løsne smuss og reise luggen igjen. Behandle merker forsiktig i stedet for å skrubbe dem dypere inn i materialet. En egnet impregnering gjør at vann og flekker perler av. Legg den på igjen etter rens, og følg alltid bruksanvisningen.</p><h2>Tekniske tekstiler og veganske materialer</h2><p>Flekkrens tekstil og veganske overdeler med en fuktig klut og mild såpe. Ikke bruk blekemiddel, løsemidler eller vaskemaskin. Når paret er rent, lar du det lufttørke i romtemperatur og avslutter med et lett lag impregnering som passer materialet.</p><h2>Gummi og polerte overflater</h2><p>Tørk av gummierte overdeler og såler med en fuktig klut så snart du kan etter kontakt med gjørme eller veisalt. Bruk en tørr poleringsklut på polerte overflater for å få tilbake glansen uten å ripe dem.</p><h2>Gode vaner</h2><p>Løsne lissene før du tar av skoene, bruk skohorn, og bytt mellom par slik at hvert av dem får hvile og tørke. Lagre dem utenfor direkte sollys, og hold formen med papir eller skoblokk.</p><h2>Trenger du litt hjelp?</h2><p>Stikk innom <a href="/pages/contact-us">butikken vår i Oslo</a> for råd og en gratis skopuss. Vil du vite mer om materialene og produksjonen, kan du lese om <a href="/pages/materials">materialer og produksjon</a>.</p>` },
  "/pages/contact-us": { title: "Kontakt skobutikken vår i Oslo", eyebrow: "Ta kontakt", heading: "Kontakt oss", copy: `<div class="contact-layout"><img src="/brand-assets/contact-store.jpg" alt="New Movements-teamet utenfor butikken i Oslo" width="1600" height="1067" loading="eager" decoding="async"><div class="contact-details"><p><a href="mailto:store@newmovements.com">store@newmovements.com</a></p><p><a href="https://maps.app.goo.gl/Pzx9rjb4sbFoEdZc7" rel="external">Finn veien →</a></p><address><strong>New Movements AS</strong><br>Nedre Slottsgate 8<br>0157 Oslo</address><p>Org.nr.: 920 443 664</p><p>Trenger du hjelp med størrelse, levering, retur eller en ordre, send oss en e-post eller stikk innom butikken i Oslo.</p></div></div>` },
  "/pages/returns": { title: "Retur og bytte av sko", eyebrow: "Retur", heading: "Sørg for at størrelsen stemmer.", copy: `<p>Gratis retur innen 30 dager og gratis bytte. Prøv skoene innendørs, og behold dem i ny stand med originalemballasjen til du er sikker på størrelsen. Kontakt oss med ordrenummeret, så får du en forhåndsbetalt returetikett og instruksjoner for retur.</p><p><a href="/policies/refund-policy">Les returvilkårene →</a></p>` },
  "/pages/terms-and-conditions": { title: "Vilkår og betingelser", eyebrow: "Vilkår", heading: "Vilkår og betingelser.", copy: `<p>Selgeren din er New Movements AS, organisasjonsnummer 920 443 664, Nedre Slottsgate 8, 0157 Oslo. Kontakt oss på <a href="mailto:store@newmovements.com">store@newmovements.com</a>.</p><h2>Bestilling og betaling</h2><p>Du må være over 18 år for å bestille. Kontroller produkt, størrelse, leveringsland og totalsum før du betaler. Prisene vises i valutaen du har valgt og inkluderer avgifter og toll der dette gjelder. Levering er gratis til landene vi sender til. Lagerbeholdningen sjekkes før betaling, og lagrede opplysninger i kassen reserverer ikke varen.</p><p>Betalingen fullføres på en sikker betalingsside. Ta vare på ordrebekreftelsen hvis du trenger hjelp senere. New Movements kan be om flere opplysninger før en ordre godtas, og vi tar ikke imot bestillinger for videresalg.</p><h2>Levering, retur og klager</h2><p>Leveringsmåte og forventet leveringstid vises i kassen. Ved kjøp i nettbutikken har du 30 dager fra levering til å melde retur, og returfrakten er gratis. Varene må være i ny stand med emballasje og merkelapper. Se <a href="/pages/returns">instruksjonene for retur</a> og <a href="/policies/shipping-policy">fraktvilkårene</a>.</p><p>Er det noe feil med kjøpet, kontakt oss med kjøpsbekreftelse og bilder. Vilkårene våre begrenser ikke rettighetene du har som forbruker etter norsk lov.</p><h2>Personvern og bruk av nettsiden</h2><p>I <a href="/policies/privacy-policy">personvernerklæringen</a> kan du lese hvordan vi behandler ordreopplysninger og påmelding til nyhetsbrev. Bruk nettsiden lovlig, og respekter innholdet og de immaterielle rettighetene til New Movements.</p>` },
  "/pages/join": { title: "Bli med i fellesskapet vårt", eyebrow: "Bli med", heading: "Beveg deg med oss.", copy: `<p>Fellesskapet rundt New Movements samler sko, kunst, design og menneskene som former en mer sirkulær fremtid. Følg med på kommende slipp og arrangementer, eller stikk innom NM Community Center i Oslo.</p><p><a href="/pages/contact-us">Besøk flaggskipbutikken →</a></p><p><a href="/pages/career-opportunities">Jobbmuligheter →</a></p>` },
  "/pages/career-opportunities": { title: "Jobbmuligheter", eyebrow: "Jobb hos oss", heading: "Bygg den neste bevegelsen.", copy: `<p>New Movements er et uavhengig Oslo-merke som jobber med sko, materialutvikling, butikk og fellesskap. Ledige stillinger lyses ut gjennom de offisielle kanalene våre.</p><p>Vil du sende en gjennomtenkt søknad på eget initiativ, skriv til <a href="mailto:store@newmovements.com">store@newmovements.com</a> med en kort introduksjon og relevant erfaring.</p>` },
  "/pages/warranty-policy": { title: "Garantivilkår for sko", eyebrow: "Kundeservice", heading: "Garantivilkår.", copy: `<p>Oppstår det en mistenkt produksjonsfeil, slutt å bruke produktet og kontakt New Movements med ordrenummer, en beskrivelse og tydelige bilder. Normal bruksslitasje, uhell og feil pleie vurderes for seg, atskilt fra produksjonsfeil.</p><p><a href="mailto:store@newmovements.com">Kontakt kundeservice →</a></p>` },
  "/policies/privacy-policy": { title: "Personvernerklæring", eyebrow: "Vilkår", heading: "Personvernerklæring.", copy: `<p>New Movements AS, Nedre Slottsgate 8, 0157 Oslo, er behandlingsansvarlig for kundeopplysningene dine. Kontakt <a href="mailto:store@newmovements.com">store@newmovements.com</a> hvis du har spørsmål om personvern.</p><h2>Ordrer og kundeservice</h2><p>Vi bruker navn, e-postadresse, telefonnummer, leveringsadresse og ordreopplysninger for å gjennomføre betalingen, levere kjøpet og håndtere kundeservice, retur og klager. ReAI drifter butikken og ordrehåndteringen vår, og Adyen behandler betalingsopplysningene. Leveringsopplysninger deles med transportøren du velger. Ordre- og regnskapsdokumentasjon oppbevares så lenge loven krever.</p><h2>På enheten din</h2><p>Handlekurven lagres i nettleseren din. Leveringslandet og valutaen du velger, lagres i en innstillingscookie. Kontakt- og adresseopplysninger fra en uferdig bestilling lagres i denne nettleserfanen i opptil 24 timer, sammen med en automatisk lagring på serveren, slik at du kan fortsette der du slapp. Betalingstokener og samtykke til nyhetsbrev lagres ikke i det utkastet.</p><h2>E-post</h2><p>Påmelding til nyhetsbrevet er frivillig. Når du ber om velkomsttilbudet, får du den gjeldende CC-rabatten og oppdateringer på e-post. Du kan melde deg av med lenken i enhver markedse-post. En varsling om at en størrelse er tilbake på lager gir én e-post for det produktet og den størrelsen, utløper etter 180 dager og melder deg ikke på nyhetsbrevet.</p><h2>Statistikk for butikken</h2><p>Butikken registrerer side- og produktvisninger, endringer i handlekurven og visninger av kassen med kortlevde, tilfeldige identifikatorer for nettleserfanen. Hendelsene inneholder ikke navn, e-postadresse, telefonnummer, adresse eller spørringsparametere fra URL-en. Vi respekterer Global Privacy Control og Do Not Track. Lenker i markedse-post måler klikk, og vi bruker ikke sporingspiksler for åpning av e-post.</p><h2>Rettighetene dine</h2><p>Du kan be om innsyn, retting, sletting eller en kopi av opplysningene dine, trekke tilbake et samtykke eller protestere mot behandlingen ved å kontakte oss. Noe dokumentasjon må vi oppbevare på grunn av lovpålagte krav. Du kan klage til <a href="https://www.datatilsynet.no/" rel="external">Datatilsynet</a>.</p>` },
  "/policies/refund-policy": { title: "Refusjon og retur", eyebrow: "Vilkår", heading: "Returvilkår.", copy: `<p>Du har 30 dager fra levering til å melde retur av et kjøp i nettbutikken. Returfrakten er gratis. Produktene må være i ny stand, med originalemballasje og merkelapper.</p><p>Bruk den forhåndsbetalte returetiketten og returskjemaet som ligger i pakken. Legg skoesken i en ytre beskyttende emballasje, og fest aldri fraktetiketten direkte på skoesken. Mangler etiketten eller skjemaet, kontakt <a href="mailto:store@newmovements.com">store@newmovements.com</a> med ordrenummeret.</p><p>Når vi har mottatt og godkjent returen, kan det ta opptil 14 virkedager før pengene er tilbake. <a href="/pages/returns">Se retur og bytte</a> for fullstendige instruksjoner.</p>` },
  "/pages/gift-cards": { title: "Hjelp med gavekort", eyebrow: "Kundeservice", heading: "Gavekort", copy: `<p>Trenger du hjelp med et New Movements-gavekort du allerede har, kontakt <a href="mailto:store@newmovements.com">store@newmovements.com</a> før du bestiller. Da hjelper vi deg med å bruke beløpet.</p><p>Nye digitale gavekort kan foreløpig ikke kjøpes på nett.</p><a class="outline-button" href="/pages/contact-us">Kontakt oss</a>` },
  "/policies/shipping-policy": { title: "Leverings- og fraktvilkår", eyebrow: "Vilkår", heading: "Fraktvilkår.", copy: `<p>Tilgjengelige leveringsmåter, begrensninger for leveringsland og den bekreftede leveringstiden vises i den sikre kassen. Avgifter og toll er inkludert for alle land vi sender til. Levering er gratis: PostNord eller Bring i Norge, Sverige og Danmark, og DHL Express til alle andre land vi sender til. Du blir ikke bedt om å betale importavgifter ved levering.</p>` },
};

export const STORY_PAGE = {
  title: "Historien om skomakertradisjonen vår",
  description: "Fire generasjoner norsk skomakerhåndverk, fra Johnny Evensen i 1916 til New Movements i dag.",
  railHeading: "Rett fra bilen",
  article: (figure) => `<article class="story-copy"><h1>Vår historie</h1><p>Evensen bygger på en familietradisjon som begynte i 1916, da Johnny Evensen satte seg fore å lage kvalitetsprodukter som tålte de nordiske årstidene og kunne vare i generasjoner. Disse verdiene ble grunnlaget for en familietradisjon av håndverk som er gitt videre.</p><p>I dag er de grunnlaget for designfilosofien vår, for europeisk produksjon og for reparasjon og resirkulering. Et produkt er aldri bedre enn materialene og menneskene bak det.</p>${figure("/brand-assets/story-johnny.jpg", "Johnny Evensen, skomaker i første generasjon")}<p>Derfor styrer materialene og produksjonsvalgene hver beslutning, og prisen følger etter. Produktene våre blir brukt, testet og forbedret under virkelige forhold – fra byen til fjorden – slik at de holder den høyeste standarden for deg.</p><section><h2>Johnny Evensen</h2><p>Skomakermester Nils Jonny Evensen ble født i 1893 i Oslo. Han gikk i lære hos kongelig hoffskomaker H. A. Solberg i Oslo. Videre utdanning omfattet et kurs i mønsterkonstruksjon i Tyskland og studieopphold i Leipzig og Nürnberg. Han arbeidet i Danmark til 1916. Mange husker nok fortsatt skomakeren i det lille huset Peder Dahl bygde ved siden av Øiestads hus på Osloveien, også kjent som Grytebua. Verkstedet, som het Askim Skotøireparasjonsverksted, ble drevet av Rolf Evensen og faren hans, og var i drift et godt stykke inn i årene etter krigen. I tillegg til vanlig reparasjonsarbeid og produksjon av nytt skotøy sydde de også fotballsko.</p><p class="story-source">— Opprinnelig tekst fra Askim museum</p></section>${figure("/brand-assets/story-rolf.jpg", "Rolf Johnny Evensen, skomaker i andre generasjon")}<section><h2>Rolf Johnny Evensen</h2><p>Født i 1918 i Stavern. Han gikk i lære hos faren sin og tok fagbrev som skomaker. Han var formann ved Norrøna Skofabrikk utenfor Hamar til han gikk av med pensjon. I 1936 lagde han spesialsydde fotballsko kalt «Even Spesial», tilpasset hver enkelt spiller.</p><p>Ordtak får av og til sin bekreftelse på de mest overraskende måter. «Nød lærer naken kvinne å spinne», heter det i et gammelt ordtak, men Rolf Evensen kunne bekrefte at nøden også lærer skoløse folk å sko seg selv. Under krigen kom folk med gamle håndvesker, kofferter og liknende som skulle bli skotøy der det var mulig. En koffert på føttene var å foretrekke framfor datidens papir- og fiskeskinnssko. I 1954 gikk Rolf Evensen ut av driften, mens Evensen senior holdt det gående en stund til i de gamle lokalene.</p><p class="story-source">— Opprinnelig tekst fra Askim museum</p></section>${figure("/brand-assets/story-knut.jpg", "Knut Evensen, skomaker i tredje generasjon")}<section class="story-generation story-generation--brief"><h2>Knut Evensen</h2><p>Født i 1954 i Hamar. Han gikk i farens fotspor, lagde mokasiner og arbeidet i farens fabrikk.</p></section>${figure("/brand-assets/story-martin.jpg", "Martin Evensen, grunnleggeren av New Movements")}<section class="story-generation story-generation--brief"><h2>Martin Evensen</h2><p>Født i 1990 i Oslo. Han studerte varehandel og skodesign ved Academy of Art University i San Francisco. I 2017 valgte Martin Evensen, skomaker i fjerde generasjon og grunnlegger av New Movements, å ta arven i en ny retning: en retning definert av sirkularitet, nytenkning og en moderne forståelse av hva ansvarlig håndverk er.</p></section></article>`,
};

export const MATERIALS_PAGE = {
  title: "Skopleie og materialer",
  description: "Pleieråd for skinn, semsket skinn, tekniske tekstiler og gummierte sko fra New Movements.",
  careHeading: "Skopleie",
  railHeading: "Rett fra bilen",
  guide: `<section class="materials-page"><article class="materials-guide"><h1 class="sr-only">Skopleie og materialer</h1><p>I New Movements lager vi produkter som gjør hverdagen bedre gjennom komfort og gjennomtenkt design. Kvalitetsarbeidet er rotfestet i arven vår, inspirert av Rolf Evensen, som lagde slitesterke sko av kofferter da det var mangel på materialer under krigen. I dag hedrer vi den arven med førsteklasses, sirkulære materialer som er laget for å vare – og for å fornyes.</p><p>Å ta vare på skoene er en vesentlig del av å lukke kretsløpet. Når du steller materialene, forlenger du reisen deres og reduserer belastningen på miljøet.</p><figure><img src="/brand-assets/materials-recycled-rubber.webp" alt="Granulat av resirkulert gummi klargjort for sko fra New Movements" width="4032" height="3024" loading="eager" decoding="async"></figure><h2>Bli kjent med materialene</h2><p>Hvert materiale vi velger, trenger sitt eget stell for å beholde egenskapene og utseendet.</p><h3>Glatt gullsertifisert skinn</h3><p>Dette italienske skinnet kommer fra garverier med LWG Gold-sertifisering og er tykt, mykt og slitesterkt. Skinn trenger fett for å holde seg mykt. Bruk en god lærvoks jevnlig, slik at det ikke tørker ut eller sprekker. Avslutt med impregnering som beskytter mot vann og flekker.</p><h3>Semsket skinn og nubuck</h3><p>Disse materialene er usedvanlig myke og puster godt, men de er naturlig porøse. Bruk en egen semsket børste for å fjerne overflatesmuss og reise luggen igjen. Impregner ofte – det er avgjørende for å holde dem vannavvisende.</p><h3>Tekniske tekstiler og veganske materialer</h3><p>Utviklet for ytelse, laget av resirkulerte PET-flasker og organiske materialer. De krever lite stell og kan flekkrenses med en fuktig klut. Et lett lag impregnering gjør at smuss og væske perler av.</p><h3>Teknisk semsket skinn og nubuck</h3><p>Spanske spesialmaterialer utviklet for slitasjen i hverdagen. Tørk av dem med en myk, tørr klut for å fjerne støv. Impregnering nå og da forsterker den vannavvisende egenskapen de allerede har.</p><h3>Polerte og gummierte overflater</h3><p>Fra høyglanset Polido-skinn til gummierte overdeler som tåler vær. Bruk en myk poleringsklut på polerte overflater, og en fuktig klut for å fjerne gjørme eller veisalt fra gummierte flater.</p><figure><img src="/brand-assets/materials-craft.webp" alt="En håndverker i New Movements arbeider med materialer til sko" width="2715" height="4066" loading="lazy" decoding="async"></figure><h2>Rådene som gir paret et langt liv</h2><p><strong>Varmen gjør jobben:</strong> sålene våre i ren gummi kan kjennes stive i starten. Kroppsvarmen myker opp gummien mens du går, og paret blir mer fleksibelt og komfortabelt for hvert skritt.</p><p><strong>Lissene gir støtte:</strong> stram alltid lissene nedenfra og opp. Vil du ha ekstra hælfeste, bruker du det øverste lissehullet for å «låse» foten på plass.</p><p><strong>Hjelp fra fagfolk:</strong> du er alltid velkommen i flaggskipbutikken vår for en prat og en <strong>gratis skopuss</strong>, slik at paret ditt holder seg i form.</p><h2>Vi lukker kretsløpet</h2><p>New Movements har aldri salg, fordi vi tror på den varige verdien av produktene våre. Når skoene dine til slutt er utslitt, kan du levere dem inn i en New Movements-butikk. Vi sørger for at materialene brukes på nytt, og du får <strong>20 prosent rabatt</strong> på neste par, slik at bevegelsen fortsetter.</p></article></section>`,
};

